-- KINI step 1: operational PostgreSQL schema. Apply explicitly, never from a request.
CREATE TABLE IF NOT EXISTS households (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, name TEXT NOT NULL, age INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS local_accounts (id UUID PRIMARY KEY, login_name TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS account_households (account_id UUID NOT NULL REFERENCES local_accounts(id) ON DELETE CASCADE, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('owner','editor','viewer')), PRIMARY KEY (account_id, household_id));
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash TEXT PRIMARY KEY, account_id UUID NOT NULL, household_id BIGINT NOT NULL, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, revoked_at BIGINT, FOREIGN KEY (account_id, household_id) REFERENCES account_households(account_id, household_id) ON DELETE CASCADE, CHECK (expires_at > created_at));
CREATE INDEX IF NOT EXISTS account_household_lookup ON account_households(household_id);
CREATE INDEX IF NOT EXISTS auth_session_expiry ON auth_sessions(expires_at);
CREATE TABLE IF NOT EXISTS ingredients (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, canonical_name TEXT, category TEXT, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS ingredient_aliases (ingredient_id BIGINT NOT NULL REFERENCES ingredients(id) ON DELETE CASCADE, alias TEXT NOT NULL UNIQUE, normalized_alias TEXT);
CREATE TABLE IF NOT EXISTS unit_conversions (ingredient_id BIGINT NOT NULL REFERENCES ingredients(id) ON DELETE CASCADE, unit TEXT NOT NULL, grams DOUBLE PRECISION NOT NULL, PRIMARY KEY (ingredient_id, unit));
CREATE TABLE IF NOT EXISTS inventory_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, ingredient_id BIGINT REFERENCES ingredients(id), original_name TEXT, quantity DOUBLE PRECISION, unit TEXT, quantity_g DOUBLE PRECISION NOT NULL DEFAULT 0, data_status TEXT NOT NULL DEFAULT 'unknown', product_name TEXT, label_confirmed BOOLEAN NOT NULL DEFAULT FALSE, expiry_date TEXT, freshness_state TEXT, use_by TEXT, opened_at TEXT, received_at TEXT);
CREATE TABLE IF NOT EXISTS inventory_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, client_event_id UUID NOT NULL, source TEXT NOT NULL CHECK (source IN ('mock','yolo','manual')), action TEXT NOT NULL CHECK (action IN ('stock_in','stock_out')), detected_label TEXT NOT NULL, confidence DOUBLE PRECISION, payload_sha256 TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending_confirmation' CHECK (status IN ('pending_confirmation','applied','rejected')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), applied_at TIMESTAMPTZ, inventory_item_id BIGINT REFERENCES inventory_items(id), confirmation_sha256 TEXT, UNIQUE (household_id, client_event_id));
CREATE TABLE IF NOT EXISTS inventory_sync_state (household_id BIGINT PRIMARY KEY REFERENCES households(id) ON DELETE CASCADE, inventory_version BIGINT NOT NULL DEFAULT 0, last_applied_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS inventory_event_changes (event_id BIGINT PRIMARY KEY REFERENCES inventory_events(id), ingredient_id BIGINT NOT NULL REFERENCES ingredients(id), inventory_item_id BIGINT NOT NULL REFERENCES inventory_items(id), quantity_g DOUBLE PRECISION NOT NULL, before_quantity_g DOUBLE PRECISION NOT NULL, after_quantity_g DOUBLE PRECISION NOT NULL, confirmed_by UUID NOT NULL REFERENCES local_accounts(id), confirmed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS meal_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id) ON DELETE CASCADE, meal_type TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS meal_session_participants (session_id BIGINT NOT NULL REFERENCES meal_sessions(id) ON DELETE CASCADE, member_id BIGINT NOT NULL REFERENCES members(id) ON DELETE CASCADE, PRIMARY KEY(session_id, member_id));
CREATE TABLE IF NOT EXISTS active_data_releases (source_code TEXT PRIMARY KEY, release_id TEXT NOT NULL, cache_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS meal_data_context (meal_session_id BIGINT NOT NULL REFERENCES meal_sessions(id) ON DELETE CASCADE, source_code TEXT NOT NULL, release_id TEXT NOT NULL, PRIMARY KEY(meal_session_id, source_code));
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES ('001_step1_postgresql') ON CONFLICT DO NOTHING;
REVOKE ALL ON households, members, local_accounts, account_households, auth_sessions, ingredients, ingredient_aliases, unit_conversions, inventory_items, inventory_events, inventory_sync_state, inventory_event_changes, meal_sessions, meal_session_participants, active_data_releases, meal_data_context FROM PUBLIC;
